<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;

if(Auth::role()!=='super_admin'){http_response_code(403);exit('Acesso restrito ao Super ADM.');}$moduleLabels=['menu'=>'Cardápio/PDV','delivery'=>'Delivery/Retirada','restaurant'=>'Mesas/Cozinha','events'=>'Eventos/Ingressos','loyalty'=>'CRM/Fidelidade'];
if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();$action=(string)($_POST['action']??'');try{
    if($action==='select-tenant'){$id=(int)($_POST['tenant_id']??0);Auth::selectTenant($id>0?$id:null);Auth::audit('superadmin.tenant_selected','tenant',$id?(string)$id:null);em_flash('ok',$id?'Empresa selecionada.':'Contexto global selecionado.');em_go('superadmin');}
    if($action==='tenant-status'){$id=(int)$_POST['tenant_id'];$status=(string)($_POST['status']??'active');if(!in_array($status,['active','suspended','cancelled'],true))throw new RuntimeException('Status inválido.');$s=$pdo->prepare('UPDATE tenants SET status=? WHERE id=?');$s->execute([$status,$id]);if(!$s->rowCount())throw new RuntimeException('Empresa não encontrada.');if(Auth::tenantId()===$id&&$status!=='active')Auth::selectTenant(null);Auth::audit('superadmin.tenant_status','tenant',(string)$id,['status'=>$status]);em_flash('ok','Status atualizado.');em_go('superadmin',['edit'=>$id]);}
    if($action==='tenant-create'){$company=trim((string)($_POST['company']??''));$admin=trim((string)($_POST['admin_name']??''));$email=mb_strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');if($company===''||$admin===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10)throw new RuntimeException('Preencha empresa, administrador, e-mail válido e senha com 10+ caracteres.');$slug=em_slug($company).'-'.substr(bin2hex(random_bytes(3)),0,6);Database::transaction(function(PDO$db)use($company,$slug,$admin,$email,$password,$moduleLabels,&$tenantId){$db->prepare('INSERT INTO tenants (name,slug,plan,status,primary_color,secondary_color) VALUES (?, ?,"premium","active","#6d4aff","#8b5cf6")')->execute([$company,$slug]);$tenantId=(int)$db->lastInsertId();$db->prepare('INSERT INTO users (tenant_id,name,email,password_hash,role,status) VALUES (?,?,?,?,"admin","active")')->execute([$tenantId,$admin,$email,password_hash($password,PASSWORD_DEFAULT)]);$m=$db->prepare('INSERT INTO tenant_modules (tenant_id,module_key,enabled) VALUES (?,?,1)');foreach(array_keys($moduleLabels)as$key)$m->execute([$tenantId,$key]);});Auth::audit('superadmin.tenant_created','tenant',(string)$tenantId,['admin_email'=>$email]);em_flash('ok','Empresa e administrador criados.');em_go('superadmin',['edit'=>$tenantId]);}
    if($action==='tenant-settings'){$id=(int)($_POST['tenant_id']??0);$name=trim((string)($_POST['name']??''));$plan=trim((string)($_POST['plan']??'premium'));$domain=trim((string)($_POST['custom_domain']??''));$support=mb_strtolower(trim((string)($_POST['support_email']??'')));$phone=trim((string)($_POST['phone']??''));$primary=trim((string)($_POST['primary_color']??'#6d4aff'));$secondary=trim((string)($_POST['secondary_color']??'#8b5cf6'));$expires=trim((string)($_POST['plan_expires_at']??''));if($name===''||!preg_match('/^[a-zA-Z0-9_-]{2,40}$/',$plan))throw new RuntimeException('Dados da empresa inválidos.');if($support!==''&&!filter_var($support,FILTER_VALIDATE_EMAIL))throw new RuntimeException('E-mail de suporte inválido.');if($domain!==''&&!preg_match('/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/i',$domain))throw new RuntimeException('Domínio personalizado inválido.');foreach([$primary,$secondary]as$color)if(!preg_match('/^#[0-9a-fA-F]{6}$/',$color))throw new RuntimeException('Cor inválida. Use formato #RRGGBB.');$expires=$expires?str_replace('T',' ',$expires):null;Database::transaction(function(PDO$db)use($id,$name,$plan,$domain,$support,$phone,$primary,$secondary,$expires,$moduleLabels){$s=$db->prepare('UPDATE tenants SET name=?,plan=?,plan_expires_at=?,custom_domain=?,support_email=?,phone=?,primary_color=?,secondary_color=? WHERE id=?');$s->execute([$name,$plan,$expires,$domain?:null,$support?:null,$phone?:null,$primary,$secondary,$id]);if(!$s->rowCount()){ $c=$db->prepare('SELECT id FROM tenants WHERE id=?');$c->execute([$id]);if(!$c->fetchColumn())throw new RuntimeException('Empresa não encontrada.');}$up=$db->prepare('INSERT INTO tenant_modules (tenant_id,module_key,enabled) VALUES (?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled)');foreach(array_keys($moduleLabels)as$key)$up->execute([$id,$key,isset($_POST['module'][$key])?1:0]);});Auth::audit('superadmin.tenant_settings','tenant',(string)$id,['plan'=>$plan,'domain'=>$domain]);em_flash('ok','Plano, marca e módulos atualizados.');em_go('superadmin',['edit'=>$id]);}
}catch(Throwable$e){em_flash('error',$e->getMessage());em_go('superadmin');}}
$editId=(int)($_GET['edit']??0);$edit=null;$editModules=[];if($editId){$s=$pdo->prepare('SELECT * FROM tenants WHERE id=?');$s->execute([$editId]);$edit=$s->fetch()?:null;if($edit){$m=$pdo->prepare('SELECT module_key,enabled FROM tenant_modules WHERE tenant_id=?');$m->execute([$editId]);foreach($m->fetchAll()as$r)$editModules[$r['module_key']]=(bool)$r['enabled'];}}$s=$pdo->query('SELECT t.*,(SELECT COUNT(*) FROM users u WHERE u.tenant_id=t.id) users_count,(SELECT COUNT(*) FROM business_units bu WHERE bu.tenant_id=t.id AND bu.status="active") units_count,(SELECT COUNT(*) FROM orders o WHERE o.tenant_id=t.id) orders_count,(SELECT COALESCE(SUM(o.total_cents),0) FROM orders o WHERE o.tenant_id=t.id AND o.payment_status="paid") paid_total FROM tenants t ORDER BY t.id DESC');$tenants=$s->fetchAll();$selected=Auth::tenantId();em_header('Super ADM','superadmin');?>
<div class="grid" style="grid-template-columns:minmax(310px,1fr) minmax(0,2fr)"><section><article class="card"><h2>Nova empresa</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tenant-create"><label class="span-2">Empresa<input name="company" required></label><label class="span-2">Administrador<input name="admin_name" required></label><label class="span-2">E-mail<input type="email" name="email" required></label><label class="span-2">Senha inicial<input type="password" name="password" minlength="10" required></label><button class="primary span-2">Criar empresa</button></form></article><?php if($edit):?><article class="card" style="margin-top:16px"><h2>Configurar <?= Security::e($edit['name']) ?></h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tenant-settings"><input type="hidden" name="tenant_id" value="<?= $editId ?>"><label class="span-2">Nome<input name="name" required value="<?= Security::e($edit['name']) ?>"></label><label>Plano<input name="plan" value="<?= Security::e($edit['plan']) ?>"></label><label>Vencimento<input type="datetime-local" name="plan_expires_at" value="<?= $edit['plan_expires_at']?Security::e(date('Y-m-d\TH:i',strtotime($edit['plan_expires_at']))):'' ?>"></label><label class="span-2">Domínio personalizado<input name="custom_domain" value="<?= Security::e($edit['custom_domain']??'') ?>" placeholder="cardapio.cliente.com.br"></label><label>E-mail de suporte<input type="email" name="support_email" value="<?= Security::e($edit['support_email']??'') ?>"></label><label>Telefone<input name="phone" value="<?= Security::e($edit['phone']??'') ?>"></label><label>Cor principal<input type="color" name="primary_color" value="<?= Security::e($edit['primary_color']??'#6d4aff') ?>"></label><label>Cor secundária<input type="color" name="secondary_color" value="<?= Security::e($edit['secondary_color']??'#8b5cf6') ?>"></label><div class="span-2"><strong>Módulos</strong><div class="grid" style="grid-template-columns:1fr 1fr;margin-top:8px"><?php foreach($moduleLabels as$key=>$label):?><label class="checkbox"><input type="checkbox" name="module[<?= Security::e($key) ?>]"<?= em_checked($editModules[$key]??true) ?>> <?= Security::e($label) ?></label><?php endforeach;?></div></div><button class="primary span-2">Salvar empresa</button></form></article><?php endif;?></section><section class="card"><div class="section-head"><h2>Empresas</h2><div class="actions"><span class="muted"><?= count($tenants) ?> cadastradas</span><a class="button secondary" href="<?= Security::e(em_url('/?route=backup')) ?>">Backup global</a><a class="button secondary" href="<?= Security::e(em_url('/?route=diagnostic')) ?>">Diagnóstico</a></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Empresa</th><th>Plano</th><th>Status</th><th>Estrutura</th><th>Recebido</th><th></th></tr></thead><tbody><?php foreach($tenants as$t):?><tr><td><strong><?= Security::e($t['name']) ?></strong><?php if($selected===(int)$t['id']):?> <span class="badge active">Selecionada</span><?php endif;?><br><code><?= Security::e($t['slug']) ?></code><?php if($t['custom_domain']):?><br><small class="muted"><?= Security::e($t['custom_domain']) ?></small><?php endif;?></td><td><?= Security::e($t['plan']) ?><?php if($t['plan_expires_at']):?><br><small class="muted">até <?= Security::e($t['plan_expires_at']) ?></small><?php endif;?></td><td><span class="badge"><?= Security::e($t['status']) ?></span></td><td><?= (int)$t['users_count'] ?> usuários<br><?= (int)$t['units_count'] ?> unidades<br><?= (int)$t['orders_count'] ?> pedidos</td><td><?= em_money($t['paid_total']) ?></td><td><div class="actions"><a class="button secondary" href="<?= Security::e(em_url('/?route=superadmin&edit='.(int)$t['id'])) ?>">Configurar</a><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="select-tenant"><input type="hidden" name="tenant_id" value="<?= (int)$t['id'] ?>"><button class="secondary">Entrar</button></form><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tenant-status"><input type="hidden" name="tenant_id" value="<?= (int)$t['id'] ?>"><input type="hidden" name="status" value="<?= $t['status']==='active'?'suspended':'active' ?>"><button class="secondary"><?= $t['status']==='active'?'Suspender':'Ativar' ?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div><?php em_footer();
